-- Inactive coordination only: no runtime callers, provider work or financial authority.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
DO $owner$ BEGIN
 IF current_user IN ('anon','authenticated','service_role') THEN RAISE EXCEPTION 'BILLING_WORK_OWNER'; END IF;
 IF to_regclass('public.billing_finance_event_deliveries') IS NULL OR to_regclass('public.stripe_webhook_events') IS NULL THEN RAISE EXCEPTION 'BILLING_WORK_PREREQUISITE'; END IF;
END $owner$;
-- Evidence v2 preserves bounded signed historical facts; routing-only v1 is rejected.
CREATE FUNCTION public.billing_consumer_work_shape(v jsonb,s jsonb) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public AS $shape_v2$
DECLARE k text; child jsonb;
BEGIN
 IF v IS NULL THEN RETURN false; END IF;
 IF v='null'::jsonb THEN RETURN coalesce((s->>'nullable')::boolean,false); END IF;
 IF s ? 'enum' AND NOT (s->'enum' @> jsonb_build_array(v)) THEN RETURN false; END IF;
 CASE s->>'type'
 WHEN 'string' THEN RETURN jsonb_typeof(v)='string' AND (NOT s ? 'pattern' OR v#>>'{}' ~ (s->>'pattern'));
 WHEN 'integer' THEN RETURN jsonb_typeof(v)='number' AND v::text ~ '^[0-9]+$' AND (v::text)::numeric BETWEEN coalesce((s->>'minimum')::numeric,0) AND coalesce((s->>'maximum')::numeric,9007199254740991);
 WHEN 'boolean' THEN RETURN jsonb_typeof(v)='boolean';
 WHEN 'array' THEN
  IF jsonb_typeof(v)<>'array' OR jsonb_array_length(v)>(s->>'maxItems')::integer THEN RETURN false; END IF;
  FOR child IN SELECT value FROM jsonb_array_elements(v) LOOP IF NOT public.billing_consumer_work_shape(child,s->'items') THEN RETURN false; END IF; END LOOP;
 WHEN 'object' THEN
  IF jsonb_typeof(v)<>'object' OR NOT v ?& ARRAY(SELECT jsonb_array_elements_text(s->'required')) THEN RETURN false; END IF;
  FOR k,child IN SELECT key,value FROM jsonb_each(v) LOOP
   IF NOT (s->'properties') ? k OR NOT public.billing_consumer_work_shape(child,s->'properties'->k) THEN RETURN false; END IF;
  END LOOP;
 ELSE RETURN false;
 END CASE;
 RETURN true;
END $shape_v2$;
