er":{"type":"string","enum":["entitlement"]},"consumer_version":{"type":"string","enum":["entitlement_v1"]},"scope":{"type":"string","pattern":"^acct_[A-Za-z0-9]{1,240}:(test|live)$"},"event_id":{"type":"string","pattern":"^evt_[A-Za-z0-9]{1,240}$"},"event_type":{"type":"string","enum":["charge.succeeded","charge.failed","charge.captured","charge.refunded"]},"event_created":{"type":"integer","minimum":0,"maximum":253402300799},"api_version":{"type":"string","pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}(\\.[a-z]+)?$","nullable":true},"subject_type":{"type":"string","enum":["charge"]},"subject_id":{"type":"string","pattern":"^ch_[A-Za-z0-9]{1,240}$"},"object":{"type":"object","properties":{"id":{"type":"string","pattern":"^ch_[A-Za-z0-9]{1,240}$"}},"required":["id"]},"previous":{"type":"object","properties":{"status":{"type":"string","enum":["active","trialing","past_due","unpaid","canceled","incomplete","incomplete_expired","paused","draft","open","paid","void","uncollectible","succeeded","failed","pending","requires_action"]},"cancel_at_period_end":{"type":"boolean"}},"required":[]}},"required":["version","consumer","consumer_version","scope","event_id","event_type","event_created","api_version","subject_type","subject_id","object","previous"]},"entitlement_refund":{"type":"object","properties":{"version":{"type":"integer","enum":[2]},"consumer":{"type":"string","enum":["entitlement"]},"consumer_version":{"type":"string","enum":["entitlement_v1"]},"scope":{"type":"string","pattern":"^acct_[A-Za-z0-9]{1,240}:(test|live)$"},"event_id":{"type":"string","pattern":"^evt_[A-Za-z0-9]{1,240}$"},"event_type":{"type":"string","enum":["charge.refund.updated","refund.created","refund.updated","refund.failed"]},"event_created":{"type":"integer","minimum":0,"maximum":253402300799},"api_version":{"type":"string","pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}(\\.[a-z]+)?$","nullable":true},"subject_type":{"type":"string","enum":["refund"]},"subject_id":{"type":"string","pattern":"^re_[A-Za-z0-9]{1,240}$"},"object":{"type":"object","properties":{"id":{"type":"string","pattern":"^re_[A-Za-z0-9]{1,240}$"}},"required":["id"]},"previous":{"type":"object","properties":{"status":{"type":"string","enum":["active","trialing","past_due","unpaid","canceled","incomplete","incomplete_expired","paused","draft","open","paid","void","uncollectible","succeeded","failed","pending","requires_action"]},"cancel_at_period_end":{"type":"boolean"}},"required":[]}},"required":["version","consumer","consumer_version","scope","event_id","event_type","event_created","api_version","subject_type","subject_id","object","previous"]}},"events":{"finance:checkout.session.completed":"finance_checkout_session","finance:customer.created":"finance_customer","finance:customer.subscription.created":"finance_subscription","finance:customer.subscription.updated":"finance_subscription","finance:customer.subscription.deleted":"finance_subscription","finance:invoice.finalized":"finance_invoice","finance:invoice.updated":"finance_invoice","finance:invoice.paid":"finance_invoice","finance:invoice.payment_succeeded":"finance_invoice","finance:invoice.payment_failed":"finance_invoice","finance:invoice.voided":"finance_invoice","finance:invoice.marked_uncollectible":"finance_invoice","finance:invoice_payment.paid":"finance_allocation","finance:charge.succeeded":"finance_charge_captured","finance:charge.failed":"finance_charge_failed","finance:charge.captured":"finance_charge_captured","finance:charge.refunded":"finance_charge","finance:charge.refund.updated":"finance_refund","finance:refund.created":"finance_refund","finance:refund.updated":"finance_refund","finance:refund.failed":"finance_refund","entitlement:checkout.session.completed":"entitlement_checkout_session","entitlement:customer.created":"entitlement_customer","entitlement:customer.subscription.created":"entitlement_subscription","entitlement:customer.subscription.updated":"entitlement_subscription","entitlement:customer.subscription.deleted":"entitlement_subscription_deleted","entitlement:invoice.finalized":"entitlement_invoice","entitlement:invoice.updated":"entitlement_invoice","entitlement:invoice.paid":"entitlement_invoice","entitlement:invoice.payment_succeeded":"entitlement_invoice","entitlement:invoice.payment_failed":"entitlement_invoice","entitlement:invoice.voided":"entitlement_invoice","entitlement:invoice.marked_uncollectible":"entitlement_invoice","entitlement:invoice_payment.paid":"entitlement_allocation","entitlement:charge.succeeded":"entitlement_charge_captured","entitlement:charge.failed":"entitlement_charge_captured","entitlement:charge.captured":"entitlement_charge_captured","entitlement:charge.refunded":"entitlement_charge_captured","entitlement:charge.refund.updated":"entitlement_refund","entitlement:refund.created":"entitlement_refund","entitlement:refund.updated":"entitlement_refund","entitlement:refund.failed":"entitlement_refund"}}$schemas$::jsonb; s jsonb;
BEGIN
 s:=schemas->'groups'->(schemas->'events'->>((p->>'consumer')||':'||(p->>'event_type')));
 IF s IS NULL OR NOT public.billing_consumer_work_shape(p,s) OR octet_length(p::text)>32768 OR p->>'subject_id' IS DISTINCT FROM p->'object'->>'id' THEN RETURN false; END IF;
 IF p->>'consumer'='finance' AND p->>'api_version' IS DISTINCT FROM '2023-10-16' THEN RETURN false; END IF;
 IF p->>'consumer'='finance' AND p->>'customer' IS DISTINCT FROM p->'object'->>'customer' THEN RETURN false; END IF;
 IF p->>'event_type'='charge.failed' AND p->>'consumer'='finance' AND
 (p->'object'->>'status' IS DISTINCT FROM 'failed' OR p->'object'->'paid' IS DISTINCT FROM 'false'::jsonb OR p->'object'->'amount_captured' IS DISTINCT FROM '0'::jsonb OR p->'object'->'livemode' IS DISTINCT FROM to_jsonb(right(p->>'scope',5)=':live')) THEN RETURN false; END IF;
 IF p->>'event_type'='customer.subscription.deleted' AND p->>'consumer'='entitlement' AND
 (p->'object'->>'status' IS DISTINCT FROM 'canceled' OR p->'object'->'livemode' IS DISTINCT FROM to_jsonb(right(p->>'scope',5)=':live')) THEN RETURN false; END IF;
 RETURN true;
END $evidence_v2$;
-- This foundation is unapplied: only complete v2 admission is accepted.
CREATE FUNCTION public.billing_consumer_work_evidence(p jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public AS $evidence$
 SELECT coalesce(public.billing_consumer_work_evidence_v2(p),false);
$evidence$;
CREATE TABLE public.billing_consumer_work_partitions (
 stripe_scope text NOT NULL CHECK(stripe_scope ~ '^acct_[A-Za-z0-9]{1,240}:(test|live)$'),
 consumer text NOT NULL CHECK(consumer IN ('finance','entitlement')),
 partition_kind text NOT NULL,partition_key text NOT NULL,
 scheduling_token uuid,scheduling_generation bigint NOT NULL DEFAULT 0 CHECK(scheduling_generation>=0),
 lease_until timestamptz,last_claimed_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(stripe_scope,consumer,partition_kind,partition_key),
 CHECK((consumer='finance' AND partition_kind='customer' AND partition_key ~ '^cus_[A-Za-z0-9]{1,240}$') OR
 (consumer='entitlement' AND partition_kind='user' AND partition_key ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')),
 CHECK((scheduling_token IS NULL)=(lease_until IS NULL))
);
CREATE TABLE public.billing_consumer_work (
 stripe_scope text NOT NULL CHECK(stripe_scope ~ '^acct_[A-Za-z0-9]{1,240}:(test|live)$'),
 stripe_event_id text NOT NULL CHECK(stripe_event_id ~ '^evt_[A-Za-z0-9]{1,240}$'),
 consumer text NOT NULL CHECK(consumer IN ('finance','entitlement')),
 consumer_version text NOT NULL CHECK((consumer='finance' AND consumer_version='finance_v1') OR (consumer='entitlement' AND consumer_version='entitlement_v1')),
 event_type text NOT NULL CHECK(event_type IN ('checkout.session.completed','customer.created','customer.subscription.created','customer.subscription.updated','customer.subscription.deleted','invoice.finalized','invoice.updated','invoice.paid','invoice.payment_succeeded','invoice.payment_failed','invoice.voided','invoice.marked_uncollectible','invoice_payment.paid','charge.succeeded','charge.failed','charge.captured','charge.refunded','charge.refund.updated','refund.created','refund.updated','refund.failed')),
 CHECK(evidence->>'subject_type'=CASE WHEN event_type LIKE 'customer.subscription.%' THEN 'subscription' WHEN event_type LIKE 'invoice.%' THEN 'invoice' WHEN event_type='charge.refund.updated' OR event_type LIKE 'refund.%' THEN 'refund' WHEN event_type LIKE 'charge.%' THEN 'charge' WHEN event_type='checkout.session.completed' THEN 'checkout_session' WHEN event_type='customer.created' THEN 'customer' WHEN event_type='invoice_payment.paid' THEN 'allocation' END),
 event_created bigint NOT NULL CHECK(event_created BETWEEN 0 AND 253402300799),
 evidence_version integer NOT NULL DEFAULT 2 CHECK(evidence_version=2),
 CHECK(evidence_version=(evidence->>'version')::integer),
 CHECK(evidence_version<>2 OR (evidence->>'scope'=stripe_scope AND evidence->>'event_id'=stripe_event_id AND evidence->>'consumer'=consumer AND evidence->>'consumer_version'=consumer_version AND evidence->>'event_type'=event_type AND (evidence->>'event_created')::bigint=event_created)),
 evidence jsonb NOT NULL CHECK(public.billing_consumer_work_evidence(evidence)),
 evidence_digest text NOT NULL CHECK(evidence_digest ~ '^[0-9a-f]{64}$'),
 partition_kind text,partition_key text,partition_basis text CHECK(partition_basis IN ('verified_snapshot','verified_relationship')),
 arrival_sequence bigint GENERATED ALWAYS AS IDENTITY,
 state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','processing','retry_wait','dependency_wait','completed','needs_attention')),
 next_attempt_at timestamptz NOT NULL DEFAULT now(),attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),retries integer NOT NULL DEFAULT 0 CHECK(retries>=0),
 scheduling_token uuid,scheduling_generation bigint NOT NULL DEFAULT 0 CHECK(scheduling_generation>=0),partition_generation bigint,
 lease_until timestamptz,processing_started_at timestamptz,settled_token uuid,
 failure_category text CHECK(failure_category IN ('lease_busy','dependency_unresolved','ownership_conflict','ownership_stale','ambiguous_outcome','provider_unavailable','store_unavailable','invalid_evidence','worker_expired','retry_exhausted','routing_unresolved')),
 terminal_result text CHECK(terminal_result IN ('processed','ignored')),
 created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,
 PRIMARY KEY(stripe_scope,stripe_event_id,consumer),
 FOREIGN KEY(stripe_scope,consumer,partition_kind,partition_key) REFERENCES public.billing_consumer_work_partitions ON DELETE RESTRICT,
 CHECK((partition_kind IS NULL)=(partition_key IS NULL) AND (partition_key IS NULL)=(partition_basis IS NULL)),
 CHECK((state='processing')=(scheduling_token IS NOT NULL) AND (scheduling_token IS NULL)=(lease_until IS NULL)),
 CHECK(state<>'processing' OR (partition_key IS NOT NULL AND partition_generation IS NOT NULL AND processing_started_at IS NOT NULL)),
 CHECK((state='completed')=(terminal_result IS NOT NULL) AND (state='completed')=(completed_at IS NOT NULL))
);
CREATE INDEX billing_consumer_work_ready ON public.billing_consumer_work(stripe_scope,consumer,partition_kind,partition_key,next_attempt_at,arrival_sequence) WHERE state IN ('pending','retry_wait','dependency_wait','processing');
CREATE INDEX billing_consumer_work_expired ON public.billing_consumer_work(stripe_scope,lease_until) WHERE state='processing';
CREATE INDEX billing_consumer_work_partition_active ON public.billing_consumer_work_partitions(stripe_scope,consumer,lease_until) WHERE lease_until IS NOT NULL;
CREATE FUNCTION public.billing_consumer_work_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $guard$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'BILLING_WORK_IMMUTABLE'; END IF;
 IF ROW(NEW.stripe_scope,NEW.stripe_event_id,NEW.consumer,NEW.consumer_version,NEW.event_type,NEW.event_created,NEW.evidence_version,NEW.evidence,NEW.evidence_digest,NEW.arrival_sequence,NEW.created_at)
 IS DISTINCT FROM ROW(OLD.stripe_scope,OLD.stripe_event_id,OLD.consumer,OLD.consumer_version,OLD.event_type,OLD.event_created,OLD.evidence_version,OLD.evidence,OLD.evidence_digest,OLD.arrival_sequence,OLD.created_at)
 OR (OLD.partition_key IS NOT NULL AND ROW(NEW.partition_kind,NEW.partition_key,NEW.partition_basis) IS DISTINCT FROM ROW(OLD.partition_kind,OLD.partition_key,OLD.partition_basis))
 OR (OLD.state='completed' AND NEW IS DISTINCT FROM OLD) THEN RAISE EXCEPTION 'BILLING_WORK_IMMUTABLE'; END IF;
 RETURN NEW;
END $guard$;
CREATE TRIGGER billing_consumer_work_immutable BEFORE UPDATE OR DELETE ON public.billing_consumer_work FOR EACH ROW EXECUTE FUNCTION public.billing_consumer_work_immutable();
CREATE FUNCTION public.billing_consumer_work_admit(p_scope text,p_event text,p_consumer text,p_input jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $admit$
DECLARE w public.billing_consumer_work%ROWTYPE;d text;e jsonb;
BEGIN
 IF jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR NOT p_input ?& ARRAY['consumer_version','event_type','event_created','evidence'] OR p_input-ARRAY['consumer_version','event_type','event_created','evidence']<>'{}'
 OR NOT public.billing_consumer_work_evidence(p_input->'evidence') OR jsonb_typeof(p_input->'event_created') IS DISTINCT FROM 'number' OR coalesce(p_input->>'event_created','') !~ '^[0-9]{1,12}$' THEN RAISE EXCEPTION 'BILLING_WORK_INPUT'; END IF;
 e:=p_input->'evidence';
 IF e ? 'prices' THEN e:=jsonb_set(e,'{prices}',(SELECT coalesce(jsonb_agg(value ORDER BY value#>>'{}'),'[]') FROM jsonb_array_elements(e->'prices'))); END IF;
 d:=encode(sha256(convert_to(e::text,'UTF8')),'hex');
 INSERT INTO public.billing_consumer_work(stripe_scope,stripe_event_id,consumer,consumer_version,event_type,event_created,evidence_version,evidence,evidence_digest)
 VALUES(p_scope,p_event,p_consumer,p_input->>'consumer_version',p_input->>'event_type',(p_input->>'event_created')::bigint,(e->>'version')::integer,e,d) ON CONFLICT DO NOTHING;
 SELECT * INTO w FROM public.billing_consumer_work WHERE stripe_scope=p_scope AND stripe_event_id=p_event AND consumer=p_consumer;
 IF ROW(w.consumer_version,w.event_type,w.event_created,w.evidence_version,w.evidence,w.evidence_digest) IS DISTINCT FROM ROW(p_input->>'consumer_version',p_input->>'event_type',(p_input->>'event_created')::bigint,(e->>'version')::integer,e,d) THEN RAISE EXCEPTION 'BILLING_WORK_CONFLICT'; END IF;
 RETURN jsonb_build_object('state',w.state,'generation',w.scheduling_generation);
END $admit$;
CREATE FUNCTION public.billing_consumer_work_bind(p_scope text,p_event text,p_consumer text,p_kind text,p_key text,p_basis text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $bind$
DECLARE w public.billing_consumer_work%ROWTYPE;
BEGIN
 IF p_basis IS NULL OR p_basis NOT IN ('verified_snapshot','verified_relationship') THEN RAISE EXCEPTION 'BILLING_WORK_BINDING'; END IF;
 -- Trusted server supplies independently verified routing. This grants no financial authority.
 IF p_consumer='entitlement' AND NOT EXISTS(SELECT 1 FROM auth.users WHERE id=p_key::uuid) THEN RAISE EXCEPTION 'BILLING_WORK_BINDING'; END IF;
 INSERT INTO public.billing_consumer_work_partitions(stripe_scope,consumer,partition_kind,partition_key) VALUES(p_scope,p_consumer,p_kind,p_key) ON CONFLICT DO NOTHING;
 PERFORM 1 FROM public.billing_consumer_work_partitions WHERE stripe_scope=p_scope AND consumer=p_consumer AND partition_kind=p_kind AND partition_key=p_key FOR UPDATE;
 SELECT * INTO w FROM public.billing_consumer_work WHERE stripe_scope=p_scope AND stripe_event_id=p_event AND consumer=p_consumer FOR UPDATE;
 IF NOT FOUND OR w.state='processing' OR (w.partition_key IS NOT NULL AND ROW(w.partition_kind,w.partition_key,w.partition_basis) IS DISTINCT FROM ROW(p_kind,p_key,p_basis)) THEN RAISE EXCEPTION 'BILLING_WORK_BINDING'; END IF;
 IF p_consumer='finance' AND ((w.evidence ? 'customer' AND w.evidence->>'customer' IS DISTINCT FROM p_key) OR (p_basis='verified_snapshot' AND NOT w.evidence ? 'customer')) THEN RAISE EXCEPTION 'BILLING_WORK_BINDING'; END IF;
 IF p_consumer='entitlement' AND p_basis='verified_snapshot' THEN RAISE EXCEPTION 'BILLING_WORK_BINDING'; END IF;
 IF w.partition_key IS NULL THEN
  IF w.state='completed' THEN RAISE EXCEPTION 'BILLING_WORK_BINDING'; END IF;
  UPDATE public.billing_consumer_work SET partition_kind=p_kind,partition_key=p_key,partition_basis=p_basis,updated_at=clock_timestamp() WHERE stripe_scope=p_scope AND stripe_event_id=p_event AND consumer=p_consumer;
 END IF;
 RETURN jsonb_build_object('bound',true);
END $bind$;
CREATE FUNCTION public.billing_consumer_work_claim(p_scope text,p_consumer text,p_limit integer DEFAULT 1) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $claim$
DECLARE p public.billing_consumer_work_partitions%ROWTYPE;w public.billing_consumer_work%ROWTYPE;stamp timestamptz;token uuid;result jsonb:='[]';capacity integer;
BEGIN
 IF p_scope IS NULL OR p_scope !~ '^acct_[A-Za-z0-9]{1,240}:(test|live)$' OR p_consumer IS NULL OR p_consumer NOT IN ('finance','entitlement') OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 4 THEN RAISE EXCEPTION 'BILLING_WORK_INPUT'; END IF;
 -- Application safety defaults, not provider limits: 8/scope, 4/consumer, 120s scheduling lease.
 -- Serialize capacity allocation only in this short transaction; never hold this across provider work.
 IF NOT pg_try_advisory_xact_lock(hashtextextended('billing_work_capacity:'||p_scope,0)) THEN RETURN result; END IF;
 stamp:=clock_timestamp();
 SELECT least(p_limit,8-count(*)::integer,4-count(*) FILTER(WHERE consumer=p_consumer)::integer) INTO capacity FROM public.billing_consumer_work_partitions WHERE stripe_scope=p_scope AND lease_until>stamp;
 IF capacity<=0 THEN RETURN result; END IF;
 FOR p IN SELECT * FROM public.billing_consumer_work_partitions q WHERE q.stripe_scope=p_scope AND q.consumer=p_consumer AND (q.lease_until IS NULL OR q.lease_until<=stamp)
 AND EXISTS(SELECT 1 FROM public.billing_consumer_work t WHERE t.stripe_scope=q.stripe_scope AND t.consumer=q.consumer AND t.partition_kind=q.partition_kind AND t.partition_key=q.partition_key AND ((t.state IN ('pending','retry_wait','dependency_wait') AND t.next_attempt_at<=stamp) OR (t.state='processing' AND t.lease_until<=stamp)))
 ORDER BY q.last_claimed_at NULLS FIRST,q.partition_key LIMIT 32 FOR UPDATE SKIP LOCKED LOOP
  EXIT WHEN capacity<=0;
  SELECT * INTO w FROM public.billing_consumer_work t WHERE t.stripe_scope=p_scope AND t.consumer=p_consumer AND t.partition_kind=p.partition_kind AND t.partition_key=p.partition_key
  AND ((t.state IN ('pending','retry_wait','dependency_wait') AND t.next_attempt_at<=stamp) OR (t.state='processing' AND t.lease_until<=stamp)) ORDER BY t.next_attempt_at,t.arrival_sequence LIMIT 1 FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN CONTINUE; END IF;
  token:=gen_random_uuid();
  UPDATE public.billing_consumer_work_partitions SET scheduling_token=token,scheduling_generation=scheduling_generation+1,lease_until=stamp+interval '120 seconds',last_claimed_at=stamp,updated_at=stamp WHERE stripe_scope=p_scope AND consumer=p_consumer AND partition_kind=p.partition_kind AND partition_key=p.partition_key RETURNING * INTO p;
  UPDATE public.billing_consumer_work SET state='processing',attempts=attempts+1,retries=greatest(attempts,0),scheduling_token=token,scheduling_generation=scheduling_generation+1,partition_generation=p.scheduling_generation,lease_until=p.lease_until,processing_started_at=stamp,settled_token=NULL,failure_category=CASE WHEN state='processing' THEN 'worker_expired' ELSE failure_category END,updated_at=stamp WHERE stripe_scope=p_scope AND stripe_event_id=w.stripe_event_id AND consumer=p_consumer RETURNING * INTO w;
  result:=result||jsonb_build_array(to_jsonb(w));capacity:=capacity-1;
 END LOOP;
 RETURN result;
END $claim$;
CREATE FUNCTION public.billing_consumer_work_update(p_action text,p_scope text,p_event text,p_consumer text,p_input jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $update$
DECLARE p public.billing_consumer_work_partitions%ROWTYPE;w public.billing_consumer_work%ROWTYPE;stamp timestamptz:=clock_timestamp();until_time timestamptz;target text;receipt_state text;
BEGIN
 IF p_action IS NULL OR p_action NOT IN ('renew','retry_wait','dependency_wait','complete','needs_attention') OR jsonb_typeof(p_input) IS DISTINCT FROM 'object'
 OR p_input-ARRAY['token','generation','partition_generation','delay_seconds','failure_category','terminal_result']<>'{}' THEN RAISE EXCEPTION 'BILLING_WORK_INPUT'; END IF;
 SELECT * INTO w FROM public.billing_consumer_work WHERE stripe_scope=p_scope AND stripe_event_id=p_event AND consumer=p_consumer;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_WORK_MISSING'; END IF;
 IF w.partition_key IS NOT NULL THEN
  SELECT * INTO p FROM public.billing_consumer_work_partitions WHERE stripe_scope=p_scope AND consumer=p_consumer AND partition_kind=w.partition_kind AND partition_key=w.partition_key FOR UPDATE;
 END IF;
 SELECT * INTO w FROM public.billing_consumer_work WHERE stripe_scope=p_scope AND stripe_event_id=p_event AND consumer=p_consumer FOR UPDATE;
 stamp:=clock_timestamp(); -- Refresh after any lock wait; expired ownership cannot be renewed.
 IF w.state='completed' AND p_action='complete' AND w.settled_token::text=p_input->>'token' AND w.scheduling_generation::text=p_input->>'generation' AND w.partition_generation::text=p_input->>'partition_generation' AND w.terminal_result=p_input->>'terminal_result' THEN RETURN jsonb_build_object('state','completed'); END IF;
 IF w.partition_key IS NULL THEN
  -- Unresolved routing may only be parked/escalated; it cannot execute or complete.
  IF w.state NOT IN ('pending','retry_wait','dependency_wait') OR p_action NOT IN ('dependency_wait','needs_attention') OR p_input ?| ARRAY['token','generation','partition_generation','terminal_result'] THEN RAISE EXCEPTION 'BILLING_WORK_FENCE'; END IF;
 ELSE
  IF w.state<>'processing' OR w.scheduling_token::text IS DISTINCT FROM p_input->>'token' OR w.scheduling_generation::text IS DISTINCT FROM p_input->>'generation' OR w.partition_generation::text IS DISTINCT FROM p_input->>'partition_generation'
  OR p.scheduling_token IS DISTINCT FROM w.scheduling_token OR p.scheduling_generation IS DISTINCT FROM w.partition_generation OR w.lease_until<=stamp OR p.lease_until<=stamp THEN RAISE EXCEPTION 'BILLING_WORK_FENCE'; END IF;
 END IF;
 IF p_action='renew' THEN
  IF p_input ?| ARRAY['delay_seconds','failure_category','terminal_result'] THEN RAISE EXCEPTION 'BILLING_WORK_INPUT'; END IF;
  until_time:=least(stamp+interval '120 seconds',w.processing_started_at+interval '240 seconds');
  IF until_time<=stamp THEN RAISE EXCEPTION 'BILLING_WORK_FENCE'; END IF;
  UPDATE public.billing_consumer_work_partitions SET lease_until=until_time,updated_at=stamp WHERE stripe_scope=p_scope AND consumer=p_consumer AND partition_kind=w.partition_kind AND partition_key=w.partition_key;
  UPDATE public.billing_consumer_work SET lease_until=until_time,updated_at=stamp WHERE stripe_scope=p_scope AND stripe_event_id=p_event AND consumer=p_consumer;
  RETURN jsonb_build_object('state','processing','lease_until',until_time);
 END IF;
 IF p_action='complete' THEN
  IF p_input ?| ARRAY['delay_seconds','failure_category'] OR p_input->>'terminal_result' IS NULL OR p_input->>'terminal_result' NOT IN ('processed','ignored') THEN RAISE EXCEPTION 'BILLING_WORK_INPUT'; END IF;
  IF p_consumer='finance' THEN
   SELECT state INTO receipt_state FROM public.billing_finance_event_deliveries WHERE stripe_scope=p_scope AND stripe_event_id=p_event AND consumer_version=w.consumer_version;
   IF receipt_state IS DISTINCT FROM p_input->>'terminal_result' THEN RAISE EXCEPTION 'BILLING_WORK_RECEIPT_NOT_TERMINAL'; END IF;
  ELSE
   SELECT state INTO receipt_state FROM public.stripe_webhook_events WHERE stripe_scope=p_scope AND stripe_event_id=p_event;
   IF receipt_state IS DISTINCT FROM 'processed' OR p_input->>'terminal_result'<>'processed' THEN RAISE EXCEPTION 'BILLING_WORK_RECEIPT_NOT_TERMINAL'; END IF;
  END IF;
  target:='completed';
 ELSE
  IF p_input ? 'terminal_result' OR p_input->>'failure_category' IS NULL OR p_input->>'failure_category' NOT IN ('lease_busy','dependency_unresolved','ownership_conflict','ownership_stale','ambiguous_outcome','provider_unavailable','store_unavailable','invalid_evidence','worker_expired','retry_exhausted','routing_unresolved') THEN RAISE EXCEPTION 'BILLING_WORK_INPUT'; END IF;
  IF p_action='needs_attention' THEN
   IF p_input ? 'delay_seconds' THEN RAISE EXCEPTION 'BILLING_WORK_INPUT'; END IF;
  ELSIF jsonb_typeof(p_input->'delay_seconds') IS DISTINCT FROM 'number' OR coalesce(p_input->>'delay_seconds','') !~ '^[0-9]{1,5}$' OR (p_input->>'delay_seconds')::integer NOT BETWEEN 1 AND 86400 THEN RAISE EXCEPTION 'BILLING_WORK_INPUT'; END IF;
  target:=p_action;
 END IF;
 IF w.partition_key IS NOT NULL THEN
  UPDATE public.billing_consumer_work_partitions SET scheduling_token=NULL,lease_until=NULL,updated_at=stamp WHERE stripe_scope=p_scope AND consumer=p_consumer AND partition_kind=w.partition_kind AND partition_key=w.partition_key;
 END IF;
 UPDATE public.billing_consumer_work SET state=target,next_attempt_at=CASE WHEN target IN ('retry_wait','dependency_wait') THEN stamp+make_interval(secs=>(p_input->>'delay_seconds')::integer) ELSE next_attempt_at END,
 scheduling_token=NULL,lease_until=NULL,settled_token=w.scheduling_token,failure_category=CASE WHEN target='completed' THEN NULL ELSE p_input->>'failure_category' END,
 terminal_result=CASE WHEN target='completed' THEN p_input->>'terminal_result' END,completed_at=CASE WHEN target='completed' THEN stamp END,updated_at=stamp
 WHERE stripe_scope=p_scope AND stripe_event_id=p_event AND consumer=p_consumer;
 RETURN jsonb_build_object('state',target);
END $update$;
ALTER TABLE public.billing_consumer_work ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.billing_consumer_work_partitions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.billing_consumer_work,public.billing_consumer_work_partitions FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON SEQUENCE public.billing_consumer_work_arrival_sequence_seq FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.billing_consumer_work_shape(jsonb,jsonb),public.billing_consumer_work_evidence_v2(jsonb),public.billing_consumer_work_evidence(jsonb),public.billing_consumer_work_immutable(),public.billing_consumer_work_admit(text,text,text,jsonb),public.billing_consumer_work_bind(text,text,text,text,text,text),public.billing_consumer_work_claim(text,text,integer),public.billing_consumer_work_update(text,text,text,text,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.billing_consumer_work_admit(text,text,text,jsonb),public.billing_consumer_work_bind(text,text,text,text,text,text),public.billing_consumer_work_claim(text,text,integer),public.billing_consumer_work_update(text,text,text,text,jsonb) TO service_role;
COMMIT;
